#!/usr/bin/env node
  // ensure-icons.mjs — injects real PNG binaries if LFS pointers are detected
  // Run this BEFORE pnpm build to guarantee icon files are valid PNGs.
  import { readFile, writeFile } from 'fs/promises';
  import { fileURLToPath } from 'url';
  import { dirname, join } from 'path';

  const __dirname = dirname(fileURLToPath(import.meta.url));
  const PUBLIC = join(__dirname, '..', 'public');
  const PNG_SIG = Buffer.from('89504e470d0a1a0a', 'hex');

  const ICONS = {
    'icon-192-v2.png': '',
  'icon-512-v2.png': '',
  'apple-touch-icon-v2.png': '',
  'login-screenshot.png': ''
  };

  let fixed = 0;
  for (const [name, b64] of Object.entries(ICONS)) {
    const filePath = join(PUBLIC, name);
    try {
      const data = await readFile(filePath);
      if (!data.subarray(0, 8).equals(PNG_SIG)) {
        console.log(`[ensure-icons] ${name}: LFS pointer detected, injecting real PNG (${data.length} bytes → ${b64.length * 3 / 4 | 0} bytes)`);
        await writeFile(filePath, Buffer.from(b64, 'base64'));
        fixed++;
      } else {
        console.log(`[ensure-icons] ${name}: valid PNG ✓`);
      }
    } catch (e) {
      console.log(`[ensure-icons] ${name}: not found, writing from embedded data`);
      await writeFile(filePath, Buffer.from(b64, 'base64'));
      fixed++;
    }
  }
  console.log(`[ensure-icons] done — ${fixed} file(s) fixed`);
  